"""One HTTP call per claim; durable retries belong to the database worker."""

import json
import os
import socket
import urllib.error
import urllib.request
from email.utils import parsedate_to_datetime
from time import time

from .domain import ROOT, ExtractionError, digest

ENDPOINT = "https://api.openai.com/v1/responses"


class TransientError(ExtractionError):
    def __init__(self, message, retry_after=0):
        super().__init__(message)
        self.retry_after = retry_after


def request_body(config, document_id, message):
    return {
        "model": config["model"], "temperature": config["temperature"],
        "max_output_tokens": config["max_output_tokens"], "store": False,
        "instructions": config["prompt"],
        "input": [{"role": "user", "content": json.dumps({
            "document_id": document_id, "message": message,
        }, ensure_ascii=False)}],
        "text": {"format": {"type": "json_schema", "name": "access_request",
                            "strict": True, "schema": config["schema"]}},
    }


def parse_response(response):
    try:
        if response.get("error"):
            raise ExtractionError("provider-error: check provider account/service and retry-extraction")
        if response.get("status") != "completed":
            raise ExtractionError("incomplete-response: check token budget/service; retry-extraction")
        texts = []
        for item in response["output"]:
            if item.get("type") != "message":
                continue
            if item.get("status") != "completed":
                raise ExtractionError("interrupted-message: retry-extraction")
            for part in item["content"]:
                if part["type"] == "refusal":
                    raise ExtractionError("provider-refusal: inspect message; retry with reviewed configuration")
                if part["type"] == "output_text":
                    texts.append(part["text"])
        if len(texts) != 1:
            raise ExtractionError("invalid-response: expected one JSON text; retry-extraction")
        return json.loads(texts[0])
    except (KeyError, TypeError, ValueError, AttributeError):
        raise ExtractionError("malformed-response: expected completed structured JSON; retry-extraction") from None


class OpenAIProvider:
    def extract(self, config, document_id, message):
        key = os.environ.get("API_KEY")
        if not key:
            raise ExtractionError("missing-credential: set API_KEY in worker environment; retry-extraction")
        request = urllib.request.Request(
            ENDPOINT, data=json.dumps(request_body(config, document_id, message)).encode(),
            headers={"Authorization": f"Bearer {key}", "Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(request, timeout=config["timeout_seconds"]) as response:
                payload = response.read(1_000_001)
                if len(payload) > 1_000_000:
                    raise ExtractionError("oversized-response: inspect provider configuration; retry-extraction")
                return parse_response(json.loads(payload))
        except urllib.error.HTTPError as exc:
            if exc.code in (408, 429, 500, 502, 503, 504):
                delay = 0
                retry = exc.headers.get("Retry-After", "0")
                try:
                    delay = max(0, float(retry))
                except ValueError:
                    try:
                        delay = max(0, parsedate_to_datetime(retry).timestamp() - time())
                    except (ValueError, TypeError, OverflowError):
                        pass
                # Long provider cooldowns fail visibly rather than retrying too early.
                if delay > 3600:
                    raise ExtractionError("provider-cooldown: wait for provider reset before retry-extraction") from None
                raise TransientError(f"transient-http-{exc.code}: retry scheduled", delay) from None
            raise ExtractionError(
                f"provider-http-{exc.code}: check API_KEY/model/account; retry-extraction"
            ) from None
        except (urllib.error.URLError, TimeoutError, socket.timeout):
            raise TransientError("provider-network-timeout: retry scheduled") from None
        except (ValueError, UnicodeError):
            raise ExtractionError("malformed-response: provider returned invalid JSON; retry-extraction") from None


class MockProvider:
    """Explicit replay fixtures, not a language model or general-purpose extractor."""

    def extract(self, config, document_id, message):
        fixtures = json.loads((ROOT / "fixtures/mock-responses.json").read_text())
        if digest((ROOT / "fixtures/mock-responses.json").read_bytes()) != config["fixtures_version"]:
            raise ExtractionError("mock-fixtures-changed: re-intake with current configuration")
        try:
            return fixtures[digest(message.encode())]
        except KeyError:
            raise ExtractionError("mock-unknown-message: add a reviewed fixture or use --provider openai") from None


def provider_for(config):
    return OpenAIProvider() if config["provider"] == "openai" else MockProvider()

"""Transactional shared queue with immutable source versions and attempt history."""

import json
import random
import time
import uuid
from contextlib import contextmanager
from pathlib import Path

from sqlalchemy import (
    JSON, Column, Float, ForeignKey, Integer, LargeBinary, MetaData, String, Table,
    UniqueConstraint, and_, create_engine, event, insert, select, update,
)

from .domain import ExtractionError, digest, route, validate
from .providers import TransientError, provider_for

metadata = MetaData()
documents = Table(
    "documents", metadata, Column("document_id", String, primary_key=True),
    Column("current_attempt", String, nullable=True),
)
versions = Table(
    "source_versions", metadata, Column("id", String, primary_key=True),
    Column("document_id", ForeignKey("documents.document_id"), nullable=False),
    Column("source_sha256", String, nullable=False), Column("raw", LargeBinary, nullable=False),
    UniqueConstraint("document_id", "source_sha256"),
)
attempts = Table(
    "attempts", metadata, Column("id", String, primary_key=True),
    Column("version_id", ForeignKey("source_versions.id"), nullable=False),
    Column("config", JSON, nullable=False), Column("created_at", Float, nullable=False),
    Column("state", String, nullable=False, index=True), Column("available_at", Float, nullable=False),
    Column("lease_until", Float), Column("token", String), Column("slot_id", Integer),
    Column("calls", Integer, nullable=False), Column("extraction", JSON), Column("error", String),
    Column("status", String), Column("owner", String), Column("next_action", String),
    Column("response_source", String), Column("reused_from", String),
)
events = Table(
    "events", metadata, Column("id", String, primary_key=True),
    Column("attempt_id", ForeignKey("attempts.id"), nullable=False),
    Column("at", Float, nullable=False), Column("event", String, nullable=False),
)
slots = Table(
    "worker_slots", metadata, Column("id", Integer, primary_key=True),
    Column("token", String), Column("until", Float, nullable=False),
)
limiter = Table(
    "provider_limiter", metadata, Column("id", Integer, primary_key=True),
    Column("next_call", Float, nullable=False),
)
MAX_CALLS = 3
LEASE_SECONDS = 180
GLOBAL_CONCURRENCY = 4
CALL_SPACING = 1.0  # shared across worker processes, at most 60 live calls/minute


def uid():
    return str(uuid.uuid4())


class Store:
    def __init__(self, url):
        self.engine = create_engine(url)
        self.sqlite = self.engine.dialect.name == "sqlite"
        if self.sqlite:
            @event.listens_for(self.engine, "connect")
            def configure(connection, _):
                connection.execute("PRAGMA foreign_keys=ON")
                connection.execute("PRAGMA busy_timeout=30000")

    def initialize(self):
        metadata.create_all(self.engine)
        with self.tx() as connection:
            for index in range(GLOBAL_CONCURRENCY):
                self.upsert_ignore(connection, slots, {"id": index, "until": 0})
            self.upsert_ignore(connection, limiter, {"id": 1, "next_call": 0})

    @contextmanager
    def tx(self):
        with self.engine.connect() as connection:
            if self.sqlite:
                connection.exec_driver_sql("BEGIN IMMEDIATE")
            else:
                connection.begin()
            try:
                yield connection
                connection.commit()
            except BaseException:
                connection.rollback()
                raise

    def upsert_ignore(self, connection, table, values):
        if self.sqlite:
            from sqlalchemy.dialects.sqlite import insert as dialect_insert
        else:
            from sqlalchemy.dialects.postgresql import insert as dialect_insert
        connection.execute(dialect_insert(table).values(**values).on_conflict_do_nothing())

    def locked(self, query, skip=False):
        return query if self.sqlite else query.with_for_update(skip_locked=skip)

    @staticmethod
    def log(connection, attempt_id, description):
        connection.execute(insert(events).values(
            id=uid(), attempt_id=attempt_id, at=time.time(), event=description,
        ))

    def intake(self, path, config):
        raw = Path(path).read_bytes()
        document_id = Path(path).name
        sha = digest(raw)
        with self.tx() as connection:
            self.upsert_ignore(connection, documents, {"document_id": document_id})
            document = connection.execute(self.locked(select(documents).where(
                documents.c.document_id == document_id
            ))).mappings().one()
            current = None
            if document["current_attempt"]:
                current = connection.execute(select(attempts, versions.c.source_sha256).join(
                    versions, attempts.c.version_id == versions.c.id
                ).where(attempts.c.id == document["current_attempt"])).mappings().one()
                if (current["source_sha256"] == sha and current["config"]["processing_version"]
                        == config["processing_version"]):
                    return current["id"], "unchanged"
            version = connection.execute(select(versions.c.id).where(and_(
                versions.c.document_id == document_id, versions.c.source_sha256 == sha,
            ))).scalar_one_or_none()
            if version is None:
                version = uid()
                connection.execute(insert(versions).values(
                    id=version, document_id=document_id, source_sha256=sha, raw=raw,
                ))
            attempt_id = self.new_attempt(connection, version, config)
            # Only routing inputs changed: reuse the valid extraction without a provider call.
            if (current and current["state"] == "complete" and current["source_sha256"] == sha
                    and current["config"]["extraction_version"] == config["extraction_version"]):
                extraction = validate(current["extraction"], json.loads(raw)["message"],
                                      document_id, config["schema"])
                status, owner, action = route(extraction)
                connection.execute(update(attempts).where(attempts.c.id == attempt_id).values(
                    state="complete", extraction=extraction, status=status, owner=owner,
                    next_action=action, response_source=current["response_source"],
                    reused_from=current["id"],
                ))
                self.log(connection, attempt_id, "rerouted valid extraction without model call")
            connection.execute(update(documents).where(
                documents.c.document_id == document_id
            ).values(current_attempt=attempt_id))
            return attempt_id, "created"

    def new_attempt(self, connection, version, config):
        attempt_id = uid()
        connection.execute(insert(attempts).values(
            id=attempt_id, version_id=version, config=config, created_at=time.time(),
            state="queued", available_at=time.time(), calls=0,
        ))
        self.log(connection, attempt_id, "intake queued")
        return attempt_id

    def retry(self, document_id):
        with self.tx() as connection:
            document = connection.execute(self.locked(select(documents).where(
                documents.c.document_id == document_id
            ))).mappings().one_or_none()
            if not document:
                raise ValueError("unknown document_id")
            current = connection.execute(self.locked(select(attempts).where(
                attempts.c.id == document["current_attempt"]
            ))).mappings().one()
            if current["state"] in ("queued", "running"):
                return current["id"]  # concurrent retries cannot create duplicate active jobs
            attempt_id = self.new_attempt(connection, current["version_id"], current["config"])
            connection.execute(update(documents).where(
                documents.c.document_id == document_id
            ).values(current_attempt=attempt_id))
            return attempt_id

    def claim(self):
        now = time.time()
        with self.tx() as connection:
            slot = connection.execute(self.locked(select(slots).where(
                slots.c.until <= now
            ).order_by(slots.c.id).limit(1), skip=True)).mappings().first()
            if not slot:
                return None
            job = connection.execute(self.locked(select(attempts).join(
                documents, documents.c.current_attempt == attempts.c.id
            ).where(and_(attempts.c.state == "queued", attempts.c.available_at <= now))
                .order_by(attempts.c.created_at).limit(1), skip=True)).mappings().first()
            if not job:
                return None
            if job["config"]["provider"] == "openai":
                gate = connection.execute(self.locked(select(limiter))).mappings().one()
                if gate["next_call"] > now:
                    return None
                connection.execute(update(limiter).values(next_call=now + CALL_SPACING))
            token = uid()
            connection.execute(update(slots).where(slots.c.id == slot["id"]).values(
                token=token, until=now + LEASE_SECONDS,
            ))
            values = dict(state="running", token=token, lease_until=now + LEASE_SECONDS,
                          slot_id=slot["id"], calls=job["calls"] + 1)
            connection.execute(update(attempts).where(attempts.c.id == job["id"]).values(**values))
            source = connection.execute(select(versions).where(
                versions.c.id == job["version_id"]
            )).mappings().one()
            self.log(connection, job["id"], f"claimed call {values['calls']}")
            return dict(job) | values | {"raw": source["raw"], "document_id": source["document_id"]}

    def process(self, job, provider=None):
        extraction, error, transient = None, None, None
        try:
            payload = json.loads(job["raw"])
            message = payload["message"]
            if not isinstance(message, str) or not message.strip() or len(message.split()) > 200:
                raise ValueError
        except (ValueError, KeyError, TypeError, UnicodeError):
            error = "invalid-input: supply UTF-8 JSON with a nonempty message of at most 200 words; re-intake"
        if error is None:
            try:
                result = (provider or provider_for(job["config"])).extract(
                    job["config"], job["document_id"], message,
                )
                extraction = validate(result, message, job["document_id"], job["config"]["schema"])
            except TransientError as exc:
                error, transient = str(exc), exc
            except ExtractionError as exc:
                error = str(exc)
            except Exception:
                # Do not log provider bodies/exceptions which might contain credentials.
                error = "unexpected-extraction-error: inspect provider configuration/code; retry-extraction"
        return self.finish(job, extraction, error, transient)

    def finish(self, job, extraction, error, transient=None):
        now = time.time()
        with self.tx() as connection:
            # Fencing prevents an expired/reclaimed worker from publishing a stale result.
            current = connection.execute(self.locked(select(attempts).where(and_(
                attempts.c.id == job["id"], attempts.c.state == "running",
                attempts.c.token == job["token"], attempts.c.lease_until > now,
            )))).mappings().one_or_none()
            if current is None:
                return False
            if transient and job["calls"] < MAX_CALLS:
                delay = max(transient.retry_after, min(60, 2 ** job["calls"]) + random.random())
                connection.execute(update(attempts).where(attempts.c.id == job["id"]).values(
                    state="queued", error=error, available_at=now + delay, lease_until=None, token=None,
                ))
                gate = connection.execute(self.locked(select(limiter))).mappings().one()
                connection.execute(update(limiter).values(next_call=max(gate["next_call"], now + delay)))
                self.log(connection, job["id"], f"transient failure; durable retry in {delay:.1f}s")
            else:
                status, owner, action = route(extraction) if extraction else (
                    "error", "IT Service Desk", "retry-extraction",
                )
                source = "mock" if job["config"]["provider"] == "mock" else (
                    "openai/" + job["config"]["model"]
                )
                connection.execute(update(attempts).where(attempts.c.id == job["id"]).values(
                    state="error" if error else "complete", extraction=extraction, error=error,
                    status=status, owner=owner, next_action=action, response_source=source,
                    token=None, lease_until=None,
                ))
                self.log(connection, job["id"], "failed: " + error if error else "completed")
            connection.execute(update(slots).where(and_(
                slots.c.id == job["slot_id"], slots.c.token == job["token"]
            )).values(token=None, until=0))
            return True

    def recover(self):
        """Mark expired claims as visible errors. Operator retry creates a new attempt."""
        now = time.time()
        with self.tx() as connection:
            expired = connection.execute(self.locked(select(attempts).where(and_(
                attempts.c.state == "running", attempts.c.lease_until <= now,
            )), skip=True)).mappings().all()
            for job in expired:
                connection.execute(update(attempts).where(attempts.c.id == job["id"]).values(
                    state="error", extraction=None, error="lease-expired: worker interrupted; retry-extraction",
                    status="error", owner="IT Service Desk", next_action="retry-extraction",
                    token=None, lease_until=None,
                ))
                self.log(connection, job["id"], "expired claim recovered as actionable error")
            return len(expired)

    def view(self, history_id=None):
        with self.engine.connect() as connection:
            query = select(attempts, versions.c.document_id, versions.c.source_sha256).join(
                versions, versions.c.id == attempts.c.version_id,
            )
            if history_id:
                query = query.where(versions.c.document_id == history_id)
            else:
                query = query.join(documents, documents.c.current_attempt == attempts.c.id)
            rows = connection.execute(query.order_by(
                versions.c.document_id, attempts.c.created_at,
            )).mappings().all()
            output = []
            for row in rows:
                pending = row["state"] in ("queued", "running")
                output.append({
                    "document_id": row["document_id"], "source_sha256": row["source_sha256"],
                    "attempt_id": row["id"], "version_id": row["version_id"],
                    "extraction": row["extraction"], "status": row["state"] if pending else row["status"],
                    "owner": "IT Service Desk" if pending else row["owner"],
                    "next_action": "await-extraction" if pending else row["next_action"],
                    "error": row["error"], "response_source": row["response_source"],
                    "state": row["state"], "calls": row["calls"],
