"""Compare current outputs to independently source-authored tests/expected.tsv."""

import argparse
import csv
import json
from pathlib import Path

from .domain import FIELDS, ROOT

ROUTES = {
    "owner": ("review", "System Owner", "review-request"),
    "risk": ("review", "Security Review", "review-risk-then-owner"),
    "clarify": ("needs-information", "IT Service Desk", "clarify"),
    "withdraw": ("review", "IT Service Desk", "confirm-withdrawal"),
    "inspect": ("review", "IT Service Desk", "inspect-message"),
}


def expected():
    with (ROOT / "tests/expected.tsv").open() as file:
        return [{k: None if v == "NULL" else v for k, v in row.items()}
                for row in csv.DictReader(file, delimiter="\t")]


def compare(records):
    ids = [record["document_id"] for record in records]
    if len(ids) != len(set(ids)):
        raise ValueError("duplicate current document_id")
    lookup = {record["document_id"]: record for record in records}
    matches, null_matches, routing_matches, failures = 0, 0, 0, []
    factual_errors = []
    for gold in expected():
        document_id = gold["document_id"]
        record = lookup.get(document_id)
        actual = record.get("extraction") if record else None
        for field in FIELDS:
            if actual is not None and actual.get(field) == gold[field]:
                matches += 1
                null_matches += gold[field] is None
            else:
                failures.append({"document_id": document_id, "field": field,
                                 "expected": gold[field], "actual": actual.get(field) if actual else None})
                if actual and actual.get(field) is not None:
                    factual_errors.append(failures[-1])
        for field, value in zip(("status", "owner", "next_action"), ROUTES[gold["route"]]):
            if record and record.get(field) == value:
                routing_matches += 1
            else:
                failures.append({"document_id": document_id, "field": field, "expected": value,
                                 "actual": record.get(field) if record else None})
    golds = expected()
    return {
        "scalar_matches": matches, "scalar_denominator": len(golds) * len(FIELDS),
        "null_matches": null_matches,
        "null_denominator": sum(gold[f] is None for gold in golds for f in FIELDS),
        "routing_matches": routing_matches, "routing_denominator": len(golds) * 3,
        "failures": failures, "factual_errors": factual_errors,
        "unexpected_documents": sorted(set(ids) - {g["document_id"] for g in golds}),
        "response_sources": sorted({r["response_source"] or "none" for r in records}),
    }


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("extractions", type=Path)
    args = parser.parse_args()
    result = compare([json.loads(line) for line in args.extractions.read_text().splitlines()])
    print(json.dumps(result, indent=2))
    raise SystemExit(bool(result["failures"] or result["unexpected_documents"]))


if __name__ == "__main__":
    main()
